   295:.med-row time { font-size: var(--font-size-base); color: #6f7d73; font-weight: var(--font-weight-bold); }
   296:.med-icon, .feature-icon { display: grid; place-items: center; width: 36px; height: 36px; border-radius: var(--radius-md); color: var(--color-accent-icon); background: var(--color-accent-icon-bg); }
   297:.med-copy { min-width: 0; }
   298:.med-copy h3, .alert-card h3, .next-dose h3, .timeline h3 { margin: 0; font-size: var(--font-size-xl); font-weight: var(--font-weight-black); }
   299:.med-copy p, .alert-card p, .next-dose p, .timeline p { margin: 1px 0 0; color: var(--color-text-muted); font-size: var(--font-size-md); }
   300:.taken-button { min-width: 58px; min-height: 36px; display: grid; place-items: center; border: 0; border-radius: var(--radius-lg); color: white; background: var(--color-primary-deep); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   301:.is-taken { opacity: .58; }
   302:.is-taken .taken-button { color: #426c58; background: var(--color-surface-sage-dark); }
