   398:/* ═══════════════════════════════════════════════════════════════════════
   399:   Timeline
   400:   ═══════════════════════════════════════════════════════════════════════ */
   401:.timeline { position: relative; display: grid; gap: 8px; }
   402:.timeline article { display: grid; grid-template-columns: 14px 54px 1fr auto; align-items: center; gap: 8px; min-height: 60px; }
   403:.timeline article:not(:last-child)::before { content: ""; position: absolute; left: 6px; height: 68px; margin-top: 66px; border-left: 2px solid var(--color-border-timeline); }
   404:.timeline-dot { z-index: 1; width: 13px; height: 13px; border: 3px solid var(--color-border-dot); border-radius: var(--radius-full); background: var(--color-surface-white); }
   405:.timeline-dot.complete { border-color: var(--color-accent-timeline); background: var(--color-accent-timeline); }
   406:.timeline time { color: var(--color-text-body); font-size: var(--font-size-sm); font-weight: var(--font-weight-bold); }
   407:
   408:/* ═══════════════════════════════════════════════════════════════════════
   409:   Status tag / primary button
   410:   ═══════════════════════════════════════════════════════════════════════ */
   411:.status-tag { padding: 6px 9px; border-radius: var(--radius-pill); color: var(--color-status-default); background: var(--color-status-default-bg); font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   412:.status-tag.now { color: var(--color-status-now); background: var(--color-status-now-bg); }
   413:.primary-button { width: 100%; min-height: 52px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 18px; border: 0; border-radius: var(--radius-3xl); color: white; background: var(--color-primary); font-weight: var(--font-weight-black); text-decoration: none; cursor: pointer; box-shadow: var(--shadow-primary); }
   414:
   415:/* ═══════════════════════════════════════════════════════════════════════
   416:   Scanner / prescription
   417:   ═══════════════════════════════════════════════════════════════════════ */
   418:.scan-card { text-align: center; }
   419:.scan-card .back-button, .scan-card .eyebrow { text-align: left; }
   420:.scan-card .supporting { margin-left: auto; margin-right: auto; }
   421:.scanner { position: relative; width: 100%; min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: var(--radius-7xl); color: #345845; background: var(--color-surface-scanner); cursor: pointer; overflow: hidden; }
   422:.scanner::before { content: ""; position: absolute; inset: 0; opacity: .4; background: repeating-linear-gradient(0deg, transparent 0 24px, rgba(76,112,86,.08) 25px 26px); }
   423:.scanner strong, .scanner small, .camera-orb { z-index: 1; }
   424:.scanner small { color: var(--color-text-body); }
   425:.camera-orb { display: grid; place-items: center; width: 64px; height: 64px; border-radius: var(--radius-full); color: white; background: var(--color-primary-camera); box-shadow: var(--shadow-camera); }
   426:.scan-corner { position: absolute; width: 42px; height: 42px; border-color: var(--color-accent-scan-corner); }
   427:.top-left { top: 18px; left: 18px; border-top: 3px solid; border-left: 3px solid; border-radius: var(--radius-sm) 0 0; }
   428:.top-right { top: 18px; right: 18px; border-top: 3px solid; border-right: 3px solid; border-radius: 0 var(--radius-sm) 0 0; }
   429:.bottom-left { bottom: 18px; left: 18px; border-bottom: 3px solid; border-left: 3px solid; border-radius: 0 0 0 var(--radius-sm); }
   430:.bottom-right { bottom: 18px; right: 18px; border-right: 3px solid; border-bottom: 3px solid; border-radius: 0 0 var(--radius-sm); }
   431:.text-button { margin-top: 16px; padding: 10px; border: 0; color: #557463; background: transparent; font-weight: var(--font-weight-black); cursor: pointer; }
   432:.prescription-result { display: grid; gap: 12px; margin-top: 20px; text-align: left; }
   433:.prescription-result > .feature-icon { width: 54px; height: 54px; border-radius: var(--radius-3xl); margin: 0 auto 8px; }
