   515:/* ═══════════════════════════════════════════════════════════════════════
   516:   Health / metric / weekly
   517:   ═══════════════════════════════════════════════════════════════════════ */
   518:.metric-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 18px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-cream); }
   519:.metric-card.complete { background: var(--color-surface-sage-deep); }
   520:.metric-card h3 { margin: 2px 0; font-size: var(--font-size-2xl); }
   521:.metric-card p { margin: 0; color: #78847c; font-size: var(--font-size-sm); }
   522:.metric-card small { color: #8b6b4e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
