   360:.section-title { display: flex; justify-content: space-between; align-items: center; margin: 22px 2px 12px; }
   361:.section-title h3 { margin: 0; font-size: var(--font-size-2xl); font-weight: var(--font-weight-black); }
   362:.section-title button, .section-title span { border: 0; color: var(--color-text-body); background: transparent; font-size: var(--font-size-md); font-weight: var(--font-weight-bold); }
   363:.care-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   364:.care-grid article { display: grid; gap: 5px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   365:.care-grid article span { color: #5c8069; }
   366:.care-grid strong { font-size: var(--font-size-5xl); font-weight: var(--font-weight-black); }
   367:.care-grid small { color: var(--color-text-body); font-size: var(--font-size-sm); }
   368:
   369:/* ═══════════════════════════════════════════════════════════════════════
   370:   Activity card / role strip
   371:   ═══════════════════════════════════════════════════════════════════════ */
   372:.activity-card { margin-top: 10px; padding: 15px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); }
   373:.activity-card p { margin: 0; color: var(--color-text-body); font-size: var(--font-size-md); }
   374:.activity-card p:first-child { display: flex; justify-content: space-between; margin-bottom: 5px; color: #274538; }
   375:.decision-log-card details { margin-top: 8px; color: #52685a; font-size: var(--font-size-sm); }
   376:.decision-log-card summary { cursor: pointer; font-weight: 700; }
   377:.decision-log-card dl { display: grid; grid-template-columns: 92px 1fr; gap: 5px 8px; margin: 10px 0 0; }
   378:.decision-log-card dt { font-weight: 700; text-transform: capitalize; }
   379:.decision-log-card dd { margin: 0; overflow-wrap: anywhere; }
   380:.decision-observation { display: contents; }
   381:.demo-clock-card { display: grid; gap: 9px; margin-top: 18px; padding: 16px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); background: #fffdf8; }
   382:.demo-clock-card h3, .demo-clock-card p { margin: 0; }
   383:.demo-clock-card > p:not(.eyebrow) { color: #78857c; font-size: var(--font-size-sm); line-height: 1.4; }
   384:.demo-clock-card label { color: #52685a; font-size: var(--font-size-sm); font-weight: 700; }
   385:.demo-clock-card input { min-height: 48px; padding: 8px 10px; border: 1px solid var(--color-border-card); border-radius: 14px; color: #294a3a; font: inherit; }
   386:.demo-clock-card select { min-height: 48px; padding: 8px 10px; border: 1px solid var(--color-border-card); border-radius: 14px; color: #294a3a; background: white; font: inherit; }
   387:.demo-clock-card .consent-toggle { display: flex; align-items: flex-start; gap: 10px; line-height: 1.35; }
   388:.demo-clock-card .consent-toggle input { width: 22px; min-height: 22px; margin: 0; accent-color: #668b70; }
   389:.demo-clock-card .primary-button { margin-top: 2px; }
   390:.role-strip { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; margin-bottom: 12px; padding: 12px 14px; border-radius: var(--radius-3xl); color: #426653; background: var(--color-surface-sage-light); }
   391:.role-strip div { display: grid; }
   392:.role-strip small { color: #76847b; font-size: var(--font-size-sm); }
   393:.role-strip > span { padding: 5px 8px; border-radius: var(--radius-pill); color: #4f765e; background: white; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   394:
   395:.next-dose { margin-top: 20px; background: var(--color-surface-sage-light); }
   396:.feature-icon.sage { color: var(--color-accent-sage-icon); background: var(--color-accent-sage-bg); }
   397:
   398:/* ═══════════════════════════════════════════════════════════════════════
   399:   Timeline
   400:   ═══════════════════════════════════════════════════════════════════════ */
   401:.timeline { position: relative; display: grid; gap: 8px; }
   402:.timeline article { display: grid; grid-template-columns: 14px 54px 1fr auto; align-items: center; gap: 8px; min-height: 60px; }
   403:.timeline article:not(:last-child)::before { content: ""; position: absolute; left: 6px; height: 68px; margin-top: 66px; border-left: 2px solid var(--color-border-timeline); }
   404:.timeline-dot { z-index: 1; width: 13px; height: 13px; border: 3px solid var(--color-border-dot); border-radius: var(--radius-full); background: var(--color-surface-white); }
   405:.timeline-dot.complete { border-color: var(--color-accent-timeline); background: var(--color-accent-timeline); }
   406:.timeline time { color: var(--color-text-body); font-size: var(--font-size-sm); font-weight: var(--font-weight-bold); }
   407:
   408:/* ═══════════════════════════════════════════════════════════════════════
   409:   Status tag / primary button
   410:   ═══════════════════════════════════════════════════════════════════════ */
   411:.status-tag { padding: 6px 9px; border-radius: var(--radius-pill); color: var(--color-status-default); background: var(--color-status-default-bg); font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   412:.status-tag.now { color: var(--color-status-now); background: var(--color-status-now-bg); }
   413:.primary-button { width: 100%; min-height: 52px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 18px; border: 0; border-radius: var(--radius-3xl); color: white; background: var(--color-primary); font-weight: var(--font-weight-black); text-decoration: none; cursor: pointer; box-shadow: var(--shadow-primary); }
   414:
   415:/* ═══════════════════════════════════════════════════════════════════════
   416:   Scanner / prescription
   417:   ═══════════════════════════════════════════════════════════════════════ */
   418:.scan-card { text-align: center; }
   419:.scan-card .back-button, .scan-card .eyebrow { text-align: left; }
   420:.scan-card .supporting { margin-left: auto; margin-right: auto; }
   421:.scanner { position: relative; width: 100%; min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: var(--radius-7xl); color: #345845; background: var(--color-surface-scanner); cursor: pointer; overflow: hidden; }
   422:.scanner::before { content: ""; position: absolute; inset: 0; opacity: .4; background: repeating-linear-gradient(0deg, transparent 0 24px, rgba(76,112,86,.08) 25px 26px); }
   423:.scanner strong, .scanner small, .camera-orb { z-index: 1; }
   424:.scanner small { color: var(--color-text-body); }
   425:.camera-orb { display: grid; place-items: center; width: 64px; height: 64px; border-radius: var(--radius-full); color: white; background: var(--color-primary-camera); box-shadow: var(--shadow-camera); }
   426:.scan-corner { position: absolute; width: 42px; height: 42px; border-color: var(--color-accent-scan-corner); }
   427:.top-left { top: 18px; left: 18px; border-top: 3px solid; border-left: 3px solid; border-radius: var(--radius-sm) 0 0; }
   428:.top-right { top: 18px; right: 18px; border-top: 3px solid; border-right: 3px solid; border-radius: 0 var(--radius-sm) 0 0; }
   429:.bottom-left { bottom: 18px; left: 18px; border-bottom: 3px solid; border-left: 3px solid; border-radius: 0 0 0 var(--radius-sm); }
   430:.bottom-right { bottom: 18px; right: 18px; border-right: 3px solid; border-bottom: 3px solid; border-radius: 0 0 var(--radius-sm); }
   431:.text-button { margin-top: 16px; padding: 10px; border: 0; color: #557463; background: transparent; font-weight: var(--font-weight-black); cursor: pointer; }
   432:.prescription-result { display: grid; gap: 12px; margin-top: 20px; text-align: left; }
   433:.prescription-result > .feature-icon { width: 54px; height: 54px; border-radius: var(--radius-3xl); margin: 0 auto 8px; }
   434:
   435:/* ═══════════════════════════════════════════════════════════════════════
   436:   Fields / proof
   437:   ═══════════════════════════════════════════════════════════════════════ */
   438:.field, .field-row { padding: 14px; border-radius: var(--radius-xl); background: var(--color-surface-sage); }
   439:.field { display: grid; gap: 3px; }
   440:.field small { color: #6e886f; }
   441:.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 0; background: transparent; }
   442:.proof-scanner.captured { color: #315a43; background: var(--color-surface-sage-darker); }
   443:.proof-check { z-index: 1; display: grid; place-items: center; width: 70px; height: 70px; border-radius: var(--radius-full); color: white; background: var(--color-accent-proof); box-shadow: var(--shadow-proof); }
   444:
   445:/* ═══════════════════════════════════════════════════════════════════════
   446:   Plain card / explain points / listen button
   447:   ═══════════════════════════════════════════════════════════════════════ */
   448:.plain-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 20px; padding: 16px; border-radius: var(--radius-6xl); background: var(--color-surface-cream-warm); }
   449:.plain-card h3 { margin: 2px 0 0; font-size: var(--font-size-4xl); }
   450:.plain-card small { color: #9d654d; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   451:.plain-card > button { width: 46px; height: 46px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-stop); cursor: pointer; }
   452:.explain-points { display: grid; margin-top: 14px; border: 1px solid var(--color-border-explain); border-radius: var(--radius-5xl); overflow: hidden; }
   453:.explain-points article { padding: 13px 15px; border-bottom: 1px solid var(--color-border-explain); }
   454:.explain-points article:last-child { border: 0; }
   455:.explain-points strong { font-size: var(--font-size-base); }
   456:.explain-points p { margin: 3px 0 0; color: var(--color-text-body); font-size: var(--font-size-base); line-height: 1.4; }
   457:.listen-button { width: 100%; min-height: 46px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 12px; border: 1px solid var(--color-border-listen); border-radius: var(--radius-xl); color: #496d59; background: #f4f6f0; font-weight: var(--font-weight-black); cursor: pointer; }
   458:
   459:/* ═══════════════════════════════════════════════════════════════════════
   460:   Schedule / dog message
   461:   ═══════════════════════════════════════════════════════════════════════ */
   462:.schedule-choice { display: grid; grid-template-columns: 72px 1fr auto; align-items: center; gap: 3px 10px; margin-top: 10px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   463:.schedule-choice span { grid-row: span 2; color: #6b7c70; font-size: var(--font-size-md); font-weight: var(--font-weight-black); text-transform: uppercase; }
   464:.schedule-choice strong { font-size: var(--font-size-4xl); }
   465:.schedule-choice small { color: var(--color-text-body); }
   466:.schedule-choice > svg { grid-column: 3; grid-row: 1 / span 2; }
   467:.dog-message { display: flex; align-items: center; gap: 12px; margin-top: 16px; padding: 13px; border-radius: var(--radius-3xl); color: #496a57; background: var(--color-surface-cream); }
   468:.dog-message p { margin: 0; color: #6f776f; font-size: var(--font-size-md); line-height: 1.4; }
   469:.dog-message strong { color: #4a594e; }
   470:
   471:/* ═══════════════════════════════════════════════════════════════════════
   472:   Walk screen
   473:   ═══════════════════════════════════════════════════════════════════════ */
   474:.walk-card { text-align: center; }
   475:.walk-card .back-button, .walk-card .eyebrow { text-align: left; }
   476:.walk-orb { width: 190px; height: 190px; margin: 23px auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; border: 10px solid var(--color-accent-walk-border-idle); border-radius: var(--radius-full); color: #446a55; background: #f2f5ed; transition: border-color .3s, transform .3s; }
   477:.walk-orb.active { border-color: var(--color-accent-walk-border); transform: scale(1.02); }
   478:.walk-orb strong { color: #193c2e; font-size: var(--font-size-8xl); font-weight: var(--font-weight-black); }
   479:.walk-orb small { color: #75847a; font-size: var(--font-size-sm); }
   480:.walk-stats { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0 0 8px; }
   481:.walk-stats div { display: grid; gap: 2px; border-right: 1px solid #e0e5dc; }
   482:.walk-stats div:last-child { border: 0; }
   483:.walk-stats strong { font-size: var(--font-size-4xl); font-weight: var(--font-weight-black); }
   484:.walk-stats small { color: #79857e; font-size: var(--font-size-xs); text-transform: uppercase; }
   485:.stop-button { background: var(--color-action-stop); }
   486:.walk-note { color: #7b887f; font-size: var(--font-size-sm); }
   487:.gentle-note { margin: 8px auto 0; max-width: 330px; color: #88928b; font-size: var(--font-size-sm); line-height: 1.4; }
   488:
   489:/* ═══════════════════════════════════════════════════════════════════════
   490:   World card / customize / tricks
   491:   ═══════════════════════════════════════════════════════════════════════ */
   492:.world-card { position: relative; margin-top: 18px; padding: 22px; border-radius: var(--radius-7xl); color: white; background: linear-gradient(135deg, #4f7654, #8aa36d); overflow: hidden; }
   493:.world-card::after { content: ""; position: absolute; width: 150px; height: 150px; right: -40px; bottom: -85px; border: 18px solid rgba(255,255,255,.12); border-radius: var(--radius-full); }
   494:.world-card h3 { margin: 5px 0 2px; font-size: var(--font-size-6xl); }
   495:.world-card p { margin: 0; color: rgba(255,255,255,.78); font-size: var(--font-size-md); }
   496:.world-level { font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1.5px; }
   497:.world-progress { height: 7px; margin-top: 18px; border-radius: 9px; background: rgba(255,255,255,.22); overflow: hidden; }
   498:.world-progress span { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--color-accent-progress-bar); }
   499:.customize-row { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 11px; border: 0; border-radius: var(--radius-3xl); color: #315442; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   500:.customize-row div { display: grid; gap: 2px; }
   501:.customize-row small { color: #7b817b; font-size: var(--font-size-xs); }
   502:.trick-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   503:.trick-grid article { display: grid; gap: 5px; padding: 15px; border: 1px dashed var(--color-border-trick); border-radius: var(--radius-5xl); color: #9aa29c; }
   504:.trick-grid article.earned { border: 0; color: #57735f; background: #e7efdf; }
   505:.trick-grid small { color: #818c84; font-size: var(--font-size-xs); }
   506:
   507:/* ═══════════════════════════════════════════════════════════════════════
   508:   Souvenir / screening / activity link
   509:   ═══════════════════════════════════════════════════════════════════════ */
   510:.souvenir-row, .screening-card { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 14px; border: 0; border-radius: var(--radius-4xl); color: #274538; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   511:.souvenir-row > span, .screening-card > span { display: grid; place-items: center; width: 52px; height: 52px; border-radius: var(--radius-xl); color: #9b653a; background: #ffdab0; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   512:.souvenir-row div, .screening-card div, .activity-link div { display: grid; }
   513:.souvenir-row small, .screening-card small, .activity-link small { color: #7a847c; font-size: var(--font-size-sm); }
   514:
   515:/* ═══════════════════════════════════════════════════════════════════════
   516:   Health / metric / weekly
   517:   ═══════════════════════════════════════════════════════════════════════ */
   518:.metric-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 18px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-cream); }
   519:.metric-card.complete { background: var(--color-surface-sage-deep); }
   520:.metric-card h3 { margin: 2px 0; font-size: var(--font-size-2xl); }
   521:.metric-card p { margin: 0; color: #78847c; font-size: var(--font-size-sm); }
   522:.metric-card small { color: #8b6b4e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   523:.metric-card > button { min-width: 46px; height: 38px; display: grid; place-items: center; border: 0; border-radius: var(--radius-md); color: white; background: var(--color-primary-camera); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   524:.weekly-card { margin: 12px 0; padding: 17px; border-radius: var(--radius-6xl); background: var(--color-surface-sage); }
   525:.weekly-card .card-heading { margin-bottom: 10px; }
   526:.weekly-card h3 { margin: 0; font-size: var(--font-size-3xl); }
   527:.weekly-card p { color: #6d7d73; font-size: var(--font-size-md); line-height: 1.5; }
   528:.weekly-card > strong { display: block; padding: 10px; border-radius: var(--radius-sm); color: #5d6f63; background: white; font-size: var(--font-size-sm); }
   529:.health-bubble { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 12px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #294a3a; background: white; text-align: left; cursor: pointer; }
   530:.health-bubble div { display: grid; gap: 2px; }
   531:.health-bubble small { color: #7a847c; font-size: var(--font-size-sm); }
   532:.treatment-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-bottom: 10px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); }
   533:.treatment-card div { display: grid; gap: 2px; }
   534:.treatment-card small { color: #7a847c; font-size: var(--font-size-sm); }
   535:.treatment-card button { padding: 7px 10px; border: 0; border-radius: var(--radius-xs); color: #4f6d5c; background: #e8efe4; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); cursor: pointer; }
   536:.screening-card { margin-bottom: 10px; background: var(--color-surface-cream-warm); }
   537:.activity-link { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #284538; text-decoration: none; }
   538:
   539:/* ═══════════════════════════════════════════════════════════════════════
   540:   Festival / summary
   541:   ═══════════════════════════════════════════════════════════════════════ */
   542:.festival-card { margin-top: 18px; padding: 30px 20px; border-radius: var(--radius-7xl); color: #31583f; background: linear-gradient(145deg, #ffe7b8, #f8c9a6); text-align: center; }
   543:.festival-card h3 { margin: 10px 0 4px; font-size: var(--font-size-5xl); }
   544:.festival-card p { margin: 0; color: #766d5f; font-size: var(--font-size-md); }
   545:.summary-score { display: flex; align-items: center; justify-content: space-between; margin-top: 18px; padding: 18px; border-radius: var(--radius-5xl); color: #31583f; background: var(--color-surface-sage-deep); }
   546:.summary-score strong { font-size: var(--font-size-5xl); }
   547:.summary-score span { font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   548:.summary-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 10px; }
   549:.summary-grid article { display: grid; gap: 3px; padding: 14px; border-radius: var(--radius-2xl); background: var(--color-surface-fog); }
   550:.summary-grid strong { font-size: var(--font-size-4xl); }
   551:.summary-grid small { color: #79857d; font-size: var(--font-size-xs); }
   552:.doctor-question { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding: 14px; border-radius: var(--radius-3xl); color: #805b46; background: var(--color-surface-cream); }
   553:.doctor-question small { font-size: var(--font-size-2xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   554:.doctor-question p { margin: 3px 0 0; font-size: var(--font-size-md); }
   555:
   556:/* ═══════════════════════════════════════════════════════════════════════
   557:   Settings
   558:   ═══════════════════════════════════════════════════════════════════════ */
   559:.settings-group { display: grid; gap: 9px; margin-top: 18px; }
   560:.settings-group > button { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; padding: 12px; border: 0; border-radius: var(--radius-3xl); color: #294a3a; background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   561:.settings-group > button:nth-child(1) { background: var(--color-surface-cream-alt); }
   562:.settings-group button div { display: grid; gap: 2px; }
   563:.settings-group small { color: #78857c; font-size: var(--font-size-sm); }
   564:.settings-note { display: flex; align-items: center; gap: 12px; margin-top: 14px; padding: 13px; border-radius: var(--radius-2xl); color: #65766b; background: var(--color-surface-stone-alt); }
   565:.settings-note p { margin: 0; font-size: var(--font-size-sm); line-height: 1.4; }
   566:
   567:/* ═══════════════════════════════════════════════════════════════════════
   568:   World picker / wardrobe
   569:   ═══════════════════════════════════════════════════════════════════════ */
   570:.world-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
   571:.world-picker > button { min-width: 0; display: grid; gap: 3px; padding: 6px 6px 9px; border: 2px solid transparent; border-radius: var(--radius-3xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
